 "{0} 서식지, {1}": "{0} habitat, {1}",
 "준비 중이에요": "Coming soon",
 "\n    { vec2 pq = vWp.xz / uU + (vec2(vnoise(vWp.xz * 1.3), vnoise(vWp.xz * 1.3 + 9.0)) - 0.5) * 0.5;\n      vec2 pt = (pq - uPO) / uPN; vec4 pa = texture2D(uPA, pt), pb = texture2D(uPB, pt); float pg = pb.r;\n      if (pa.r + pa.g + pa.b + pa.a + pb.r + pb.g + pb.b > 0.01) {\n        float sh = clamp(dot(diffuseColor.rgb, vec3(0.2126, 0.7152, 0.0722)) / LUM, 0.62, 1.12); // keeps the slopes and contact shadows\n        vec4 k = smoothstep(0.18, 0.72, pa); float kg = smoothstep(0.18, 0.72, pg); // inbox 67-3: a wide soft edge, no disc\n        vec3 grass = {0} * (0.92 + 0.16 * vnoise(vWp.xz * 0.9));\n        vec3 sand = {1} * (0.96 + 0.08 * vnoise(vWp.xz * 4.0));\n        vec3 dirt = {2} * (0.94 + 0.12 * vnoise(vWp.xz * 3.0)); // 17-3: a worn trail, soft (the 흙길 brush itself is drawn as a path, uPC)\n        float gv = vnoise(vWp.xz * 9.0); vec3 gravel = {3} * (0.82 + 0.3 * step(0.55, gv) - 0.12 * step(gv, 0.2));\n        vec2 fc = floor(vWp.xz * 4.0), ff = fract(vWp.xz * 4.0) - 0.5; float fh = hash12(fc), fd = length(ff - (vec2(hash12(fc + 3.1), hash12(fc + 7.7)) - 0.5) * 0.4);\n        vec3 fcol = fh > 0.93 ? {4} : fh > 0.86 ? {5} : fh > 0.79 ? {6} : {7};\n        vec3 bloom = mix({8}, fcol, (fh > 0.9 ? 0.6 : 0.0) * (1.0 - smoothstep(0.06, 0.14, fd))); // inbox 67-3: a few soft specks, not a painted carpet\n        vec3 c = diffuseColor.rgb;\n        c = mix(c, grass * sh, kg); c = mix(c, dirt * sh, k.r); c = mix(c, sand * sh, k.g); c = mix(c, gravel * sh, k.b); c = mix(c, bloom * sh, k.a);\n        // 25-1 the snow's: fresh snow with a few glints, smooth pale ice (paler streaks, a crack line here and there)\n        vec2 kb = smoothstep(0.18, 0.72, pb.gb); float sg = step(0.985, hash12(floor(vWp.xz * 14.0)));\n        vec3 snow = {9} * (0.97 + 0.05 * vnoise(vWp.xz * 1.5)) + sg * 0.12;\n        float ck = 1.0 - smoothstep(0.0, 0.04, abs(vnoise(vWp.xz * 1.1 + 3.0) - 0.5)); vec3 ice = mix({10}, {11}, 0.35 * vnoise(vWp.xz * 0.7) + 0.4 * ck);\n        c = mix(c, snow * sh, kb.x); c = mix(c, ice * sh, kb.y);\n        diffuseColor.rgb = c; } }": "\n    { vec2 pq = vWp.xz / uU + (vec2(vnoise(vWp.xz * 1.3), vnoise(vWp.xz * 1.3 + 9.0)) - 0.5) * 0.5;\n      vec2 pt = (pq - uPO) / uPN; vec4 pa = texture2D(uPA, pt), pb = texture2D(uPB, pt); float pg = pb.r;\n      if (pa.r + pa.g + pa.b + pa.a + pb.r + pb.g + pb.b > 0.01) {\n        float sh = clamp(dot(diffuseColor.rgb, vec3(0.2126, 0.7152, 0.0722)) / LUM, 0.62, 1.12); // keeps the slopes and contact shadows\n        vec4 k = smoothstep(0.18, 0.72, pa); float kg = smoothstep(0.18, 0.72, pg); // inbox 67-3: a wide soft edge, no disc\n        vec3 grass = {0} * (0.92 + 0.16 * vnoise(vWp.xz * 0.9));\n        vec3 sand = {1} * (0.96 + 0.08 * vnoise(vWp.xz * 4.0));\n        vec3 dirt = {2} * (0.94 + 0.12 * vnoise(vWp.xz * 3.0)); // 17-3: a worn trail, soft (the dirt path brush itself is drawn as a path, uPC)\n        float gv = vnoise(vWp.xz * 9.0); vec3 gravel = {3} * (0.82 + 0.3 * step(0.55, gv) - 0.12 * step(gv, 0.2));\n        vec2 fc = floor(vWp.xz * 4.0), ff = fract(vWp.xz * 4.0) - 0.5; float fh = hash12(fc), fd = length(ff - (vec2(hash12(fc + 3.1), hash12(fc + 7.7)) - 0.5) * 0.4);\n        vec3 fcol = fh > 0.93 ? {4} : fh > 0.86 ? {5} : fh > 0.79 ? {6} : {7};\n        vec3 bloom = mix({8}, fcol, (fh > 0.9 ? 0.6 : 0.0) * (1.0 - smoothstep(0.06, 0.14, fd))); // inbox 67-3: a few soft specks, not a painted carpet\n        vec3 c = diffuseColor.rgb;\n        c = mix(c, grass * sh, kg); c = mix(c, dirt * sh, k.r); c = mix(c, sand * sh, k.g); c = mix(c, gravel * sh, k.b); c = mix(c, bloom * sh, k.a);\n        // 25-1 the snow's: fresh snow with a few glints, smooth pale ice (paler streaks, a crack line here and there)\n        vec2 kb = smoothstep(0.18, 0.72, pb.gb); float sg = step(0.985, hash12(floor(vWp.xz * 14.0)));\n        vec3 snow = {9} * (0.97 + 0.05 * vnoise(vWp.xz * 1.5)) + sg * 0.12;\n        float ck = 1.0 - smoothstep(0.0, 0.04, abs(vnoise(vWp.xz * 1.1 + 3.0) - 0.5)); vec3 ice = mix({10}, {11}, 0.35 * vnoise(vWp.xz * 0.7) + 0.4 * ck);\n        c = mix(c, snow * sh, kb.x); c = mix(c, ice * sh, kb.y);\n        diffuseColor.rgb = c; } }",
 "\n    float near = 1.0 - smoothstep(14.0, 34.0, distance(cameraPosition, vWp));\n    float d = vnoise(vWp.xz * 2.3) * 0.55 + vnoise(vWp.xz * 7.5) * 0.45;\n    float speck = step(0.9, vnoise(vWp.xz * 15.0 + 7.0));\n    diffuseColor.rgb *= 1.0 + near * ((d - 0.5) * 0.2 - speck * 0.08);\n    // the lower part of the rounded edge is the cut: soil, shaded just under the wavy turf line\n    float e = min(min(vWp.x - {0}, {1} - vWp.x), min(vWp.z - {2}, {3} - vWp.z));\n    float turf = e - (TURF + 0.06 * sin((vWp.x + vWp.z) * 2.3) + 0.08 * (vnoise(vec2((vWp.x + vWp.z) * 3.0, 0.0)) - 0.5));\n    if (turf < 0.0) { {4}\n      diffuseColor.rgb = c * (1.0 - 0.35 * smoothstep(-0.2, 0.0, turf)); }\n    diffuseColor.rgb *= 1.0 - 0.2 * uWet; // 21-2: wet in the rain\n    // 15-2 첫눈: lying snow in soft drifts (bare patches between), never on the cut\n    float sn = uSnow * smoothstep(0.32, 0.58, vnoise(vWp.xz * 0.33) * 0.75 + d * 0.25 + 0.12) * step(0.0, turf);\n    diffuseColor.rgb = mix(diffuseColor.rgb, {5} * (0.94 + 0.06 * d), sn * 0.92);": "\n    float near = 1.0 - smoothstep(14.0, 34.0, distance(cameraPosition, vWp));\n    float d = vnoise(vWp.xz * 2.3) * 0.55 + vnoise(vWp.xz * 7.5) * 0.45;\n    float speck = step(0.9, vnoise(vWp.xz * 15.0 + 7.0));\n    diffuseColor.rgb *= 1.0 + near * ((d - 0.5) * 0.2 - speck * 0.08);\n    // the lower part of the rounded edge is the cut: soil, shaded just under the wavy turf line\n    float e = min(min(vWp.x - {0}, {1} - vWp.x), min(vWp.z - {2}, {3} - vWp.z));\n    float turf = e - (TURF + 0.06 * sin((vWp.x + vWp.z) * 2.3) + 0.08 * (vnoise(vec2((vWp.x + vWp.z) * 3.0, 0.0)) - 0.5));\n    if (turf < 0.0) { {4}\n      diffuseColor.rgb = c * (1.0 - 0.35 * smoothstep(-0.2, 0.0, turf)); }\n    diffuseColor.rgb *= 1.0 - 0.2 * uWet; // 21-2: wet in the rain\n    // 15-2 First Snow: lying snow in soft drifts (bare patches between), never on the cut\n    float sn = uSnow * smoothstep(0.32, 0.58, vnoise(vWp.xz * 0.33) * 0.75 + d * 0.25 + 0.12) * step(0.0, turf);\n    diffuseColor.rgb = mix(diffuseColor.rgb, {5} * (0.94 + 0.06 * d), sn * 0.92);",
 "토이브룩 오픈 베타": "Toybrook Open Beta",
 "토이브룩 · 오픈 베타": "Toybrook · Open Beta",
 "월드맵에서 <b>초원</b>에 들어가 아래 <b>둥지</b> 버튼을 누르면 알과 부화 칸이 나와요. 알을 칸에 넣고 다 되면 눌러 부화하세요. 새끼를 서식지로 보내면 도감에 올라가고, 시간이 지나면 자라요(쓰다듬기·먹이로 조금 빨리). 성장 사탕을 주면 새끼 모습 그대로 있어요.": "Enter the <b>Meadow</b> from the world map and tap the <b>Nest</b> button below to see eggs and hatching slots. Put an egg in a slot and tap it to hatch when it's ready. Send babies to the habitat to add them to your collection, and they'll grow over time (petting and food speed it up a little). Give a Growth candy and they'll stay babies.",
 "드래그로 돌려 보기, 휠·두 손가락 벌리기로 확대, 오른쪽 드래그·Shift+드래그·두 손가락 드래그로 옮기기, 두 번 눌러 가까이 보기. 진행은 이 기기에만 저장돼요.": "Drag to rotate, scroll or pinch to zoom, right-drag, Shift+drag or two-finger drag to pan, double-tap to look closer. Progress is saved only on this device.",
